{
  "aktywnosci": [
    {
      "opis": "Dzieci tworzą laurki dla mamy. Nauczyciel przygotowuje złożone na pół kartki z bloku technicznego, farby w kilku kolorach i patyczki do maczania. Dzieci malują kwiaty, serca lub wzory, odciskając patyczki na kartce. Nauczyciel pomaga napisać odręcznie „Kocham Cię, Mamo” na wewnętrznej stronie. Po wyschnięciu dzieci mogą ozdobić laurkę brokatem lub naklejkami.",
      "tytul": "Laurka dla mamy – malowanie patyczkami"
    },
    {
      "opis": "Dzieci uczą się krótkiego wierszyka i piosenki na powitanie mamy. Nauczyciel czyta prosty wierszyk (np. „Mama jest jak słońce”) i uczy dzieci refrenu piosenki „Moja mama” (znana melodia, np. „Panie Janie”). Dzieci powtarzają słowa i rytmicznie klaszczą. Na koniec każde dziecko mówi jedno zdanie, za co dziękuje mamie, a nauczyciel zapisuje na tablicy.",
      "tytul": "Wierszyk i piosenka dla mamy"
    },
    {
      "opis": "Zabawa ruchowa „Mama i dziecko”. Dzieci dobierają się w pary – jedno jest „mamą”, drugie „dzieckiem”. „Mama” prowadzi „dziecko” z zasłoniętymi oczami (lub trzymając za rękę) po sali między przeszkodami z klocków. Po chwili zamiana ról. Nauczyciel mówi: „Jak czujesz się, gdy mama cię prowadzi?”. Ćwiczy to zaufanie i empatię.",
      "tytul": "Zabawa w parze – prowadzę mamę"
    }
  ]
}
